import React, { useContext, useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { AuthContext } from "./AuthContext";

const GOOGLE_CLIENT_ID = process.env.REACT_APP_GOOGLE_CLIENT_ID;

export default function Login() {
  const { saveToken } = useContext(AuthContext);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [rememberMe, setRememberMe] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    if (window.google && GOOGLE_CLIENT_ID) {
      window.google.accounts.id.initialize({
        client_id: GOOGLE_CLIENT_ID,
        callback: handleGoogleResponse,
      });

      window.google.accounts.id.renderButton(
        document.getElementById("googleSignInDiv"),
        {
          theme: "outline",
          size: "large",
          width: "400",
          text: "continue_with",
          shape: "rectangular",
        }
      );
    }
  }, []);

  const handleGoogleResponse = async (response) => {
    const googleToken = response.credential;
    setIsLoading(true);

    try {
      const res = await fetch("http://127.0.0.1:8000/auth/google", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id_token: googleToken }),
      });

      const data = await res.json();
      if (!res.ok) {
        alert("Google login failed");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  const handleLogin = async () => {
    if (!email || !password) {
      alert("Please fill in all fields");
      return;
    }

    setIsLoading(true);
    try {
      const res = await fetch("http://127.0.0.1:8000/auth/login", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        alert(data.detail || "Invalid credentials");
        return;
      }

      saveToken(data.token, data.user);
      navigate("/join");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      background: "linear-gradient(to bottom right, #e0f2f1, #b2dfdb)",
      padding: "20px",
      fontFamily: "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif"
    }}>
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        input:focus {
          outline: none;
          border-color: #00897b;
          box-shadow: 0 0 0 3px rgba(0, 137, 123, 0.1);
        }
        .hover-lift {
          transition: all 0.3s ease;
        }
        .hover-lift:hover {
          transform: translateY(-2px);
          box-shadow: 0 8px 24px rgba(0, 0, 0, 0.12);
        }
        button:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }
      `}</style>

      <div style={{
        width: "480px",
        background: "#ffffff",
        padding: "48px",
        borderRadius: "16px",
        boxShadow: "0 4px 20px rgba(0, 0, 0, 0.08)",
        animation: "fadeIn 0.5s ease-out"
      }}
      className="hover-lift">
        
        {/* Header */}
        <div style={{ textAlign: "center", marginBottom: "32px" }}>
          <h1 style={{
            fontSize: "28px",
            fontWeight: "700",
            color: "#0f5132",
            marginBottom: "8px"
          }}>
            Welcome back
          </h1>
          <p style={{
            color: "#5f6c7b",
            fontSize: "15px"
          }}>
            Log in to your account
          </p>
        </div>

        {/* Email Field */}
        <div style={{ marginBottom: "20px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#1a1a1a",
            marginBottom: "8px"
          }}>
            Email address
          </label>
          <input
            type="email"
            placeholder="Enter your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleLogin()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "8px",
              border: "1px solid #cbd5e1",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "#f8f9fa"
            }}
          />
        </div>

        {/* Password Field */}
        <div style={{ marginBottom: "16px" }}>
          <label style={{
            display: "block",
            fontWeight: "600",
            fontSize: "14px",
            color: "#1a1a1a",
            marginBottom: "8px"
          }}>
            Password
          </label>
          <input
            type="password"
            placeholder="Enter your password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            onKeyPress={(e) => e.key === "Enter" && handleLogin()}
            style={{
              width: "100%",
              padding: "12px 16px",
              borderRadius: "8px",
              border: "1px solid #cbd5e1",
              fontSize: "15px",
              transition: "all 0.3s ease",
              backgroundColor: "#f8f9fa"
            }}
          />
        </div>

        {/* Remember + Forgot */}
        <div style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: "24px"
        }}>
          <label style={{
            display: "flex",
            alignItems: "center",
            cursor: "pointer",
            fontSize: "14px",
            color: "#5f6c7b"
          }}>
            <input
              type="checkbox"
              checked={rememberMe}
              onChange={(e) => setRememberMe(e.target.checked)}
              style={{
                width: "16px",
                height: "16px",
                marginRight: "8px",
                cursor: "pointer",
                accentColor: "#00897b"
              }}
            />
            Remember me
          </label>
          <a href="#" style={{
            color: "#00897b",
            fontWeight: "500",
            fontSize: "14px",
            textDecoration: "none"
          }}>
            Forgot your password?
          </a>
        </div>

        {/* Sign in button */}
        <button
          onClick={handleLogin}
          disabled={isLoading}
          style={{
            width: "100%",
            background: "#1e8f55",
            color: "#fff",
            padding: "14px",
            borderRadius: "8px",
            fontSize: "16px",
            fontWeight: "600",
            border: "none",
            cursor: "pointer",
            transition: "all 0.3s ease",
            boxShadow: "0 2px 8px rgba(30, 143, 85, 0.3)"
          }}
          onMouseOver={(e) => !isLoading && (e.target.style.background = "#187d48")}
          onMouseOut={(e) => (e.target.style.background = "#1e8f55")}
        >
          {isLoading ? "Signing in..." : "Log in"}
        </button>

        {/* Divider */}
        <div style={{
          textAlign: "center",
          margin: "24px 0",
          color: "#94a3b8",
          fontSize: "14px",
          position: "relative"
        }}>
          <div style={{
            position: "absolute",
            left: 0,
            right: 0,
            top: "50%",
            height: "1px",
            background: "#e2e8f0"
          }} />
          <span style={{
            position: "relative",
            background: "#fff",
            padding: "0 16px"
          }}>
            — Or continue with —
          </span>
        </div>

        {/* Google Sign-In Button */}
        <div
          id="googleSignInDiv"
          style={{
            display: "flex",
            justifyContent: "center",
            marginBottom: "16px"
          }}
        ></div>

        {/* Signup link */}
        <div style={{
          textAlign: "center",
          marginTop: "24px",
          fontSize: "14px",
          color: "#5f6c7b"
        }}>
          Don't have an account?{" "}
          <a
            href="/signup"
            style={{
              color: "#1e8f55",
              fontWeight: "600",
              textDecoration: "none"
            }}
          >
            Sign up here
          </a>
        </div>

        {/* Load Google script */}
        <script src="https://accounts.google.com/gsi/client" async defer></script>
      </div>
    </div>
  );
}
